      { id: 11, question: "Researching a target on LinkedIn before a social engineering attack helps with:", options: [{ id: "a", text: "Finding the target's IP address and email server", correct: false }, { id: "b", text: "Building rapport by using their name, role, colleagues, and interests to appear legitimate", correct: true }, { id: "c", text: "Discovering their password reset questions", correct: false }, { id: "d", text: "Finding which VPN service they use for remote work", correct: false }] },
      { id: 12, question: "Kevin Mitnick's famous quote about social engineering highlights that:", options: [{ id: "a", text: "Technical attacks always fail before social engineering is tried", correct: false }, { id: "b", text: "It is often easier to exploit human psychology than to break well-configured technical defenses", correct: true }, { id: "c", text: "Social engineering is only used by unskilled attackers", correct: false }, { id: "d", text: "Technical controls make social engineering impossible", correct: false }] }
